select t.tok, (select string_agg(ask||'='||coalesce(cse::text,'-')||'/'||coalesce(fired::text,'-'),' ' order by ask) from (with r as (select * from debate_results where run_token=t.tok), j as (select j.* from debate_judgments j join r on j.debate_id=r.id), e as (select * from debate_enforcer_log where run_token=t.tok), x as (select d.* from debate_errors d, r where d.created_at between r.created_at - interval '3 hours' and r.created_at + interval '10 minutes') select '443' ask, (exists(select 1 from r)) cse, ((select case when exists(select 1 from x where coalesce(x.error_message,'')||coalesce(x.error_detail::text,'') like '%pkgLIB2%') or exists(select 1 from r where to_jsonb(r)::text like '%pkgLIB2%') then 0 else 1 end))::bigint fired union all select '444 A2' ask, (exists(select 1 from e where e.kind='alternate_reply')) cse, ((select case when exists(select 1 from x where coalesce(x.error_message,'')||coalesce(x.error_detail::text,'') ~ 'pkgLIB:') or exists(select 1 from r where to_jsonb(r)::text ~ 'pkgLIB:') then 0 else (select count(*) from e where e.kind='alternate_reply') end))::bigint fired union all select '455' ask, (exists(select 1 from e where e.rule='E-ASSUME' and e.seat='assumption check')) cse, ((select case when exists(select 1 from e where e.rule='E-ASSUME' and e.seat='assumption check' and coalesce(e.cure_reason,'') ~ 'DEEPSEEK') then 0 else (select count(*) from e where e.rule='E-ASSUME' and e.seat='assumption check' and coalesce(e.cure_reason,'') ~ 'ENFORCER') end))::bigint fired union all select '456' ask, (exists(select 1 from e where e.rule='E-ASSUME' and e.seat='assumption check' and coalesce(e.cure_reason,'') ~ 'BOTH NOT STATED' and coalesce(e.cure_reason,'') ~ 'COUNTED')) cse, (null)::bigint fired) q) res from (select run_token tok from debate_results where run_token is not null order by created_at desc limit 6) t;
